        /// <summary>
        /// Артикулы всех товаров в заказе через запятую.
        /// </summary>
        public string ArticleDisplay
        {
            get
            {
                if (OrderDetails == null || OrderDetails.Count == 0)
                    return "—";

                var articles = OrderDetails
                    .Where(od => od.Products != null)
                    .Select(od => od.Products.Article)
                    .Where(a => !string.IsNullOrWhiteSpace(a))
                    .ToList();

                return articles.Count == 0 ? "—" : string.Join(", ", articles);
            }
        }

